224	        Sheet sheet = sheets.lock(sheetId, user);
225	        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
226	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
227	        if (!claim.getStatus().canBecome(next)) {
228	            throw new ResponseStatusException(HttpStatus.CONFLICT,
229	                    "A " + claim.getStatus() + " claim cannot become " + next);
230	        }
231	        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
232	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "The user who opened a claim cannot settle it");
233	        }
234	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
235	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
236	        RollupService.Rollup before = rollups.snapshot(sheetId);
237	        Integer number = next == ClaimStatus.OPEN ? Integer.valueOf(sheet.takeClaimNumber()) : claim.getNumber();
238	        claim.setStatus(next);
