268	        Sheet sheet = sheets.lock(sheetId, user);
269	        Person person = people.findByIdAndSheetId(personId, sheetId)
270	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
271	        RollupService.Rollup before = rollups.snapshot(sheetId);
272	        List<Claim> theirs = claims.findBySheetIdOrderByIdDesc(sheetId).stream()
273	                .filter(c -> c.getPersonId().equals(personId))
274	                .toList();
275	        List<Claim> counting = theirs.stream().filter(c -> c.getStatus().counts()).toList();
276	        boolean anyFixed = counting.stream().anyMatch(c -> c.getDue() != null || c.isStated());
277	        boolean rated = rates.findInForce(sheetId, person.getGrade(), sheet.getToday()).isPresent();
278	        BigDecimal total = BigDecimal.ZERO.setScale(2);
279	        for (Claim c : theirs) {
280	            if (c.getStatus().counts()) {
281	                BigDecimal figure = figure(sheetId, person, c);
282	                if (figure != null) total = total.add(figure);
283	                c.bind(figure);
284	            } else {
