583	/** Where a claim is in its life: DRAFT, then OPEN, then SETTLED; a DRAFT or OPEN claim can be VOID. */
584	public enum ClaimStatus {
585	    DRAFT, OPEN, SETTLED, VOID;
586	
587	    /** Whether a claim in this status counts toward claimed and due: open and settled ones do. */
588	    public boolean counts() {
589	        return this == OPEN || this == SETTLED;
590	    }
591	
592	    /** Whether a claim in this status may move to {@code next}. */
593	    public boolean canBecome(ClaimStatus next) {
594	        return switch (next) {
595	            case OPEN -> this == DRAFT;
596	            case SETTLED -> this == OPEN;
597	            case VOID -> this == DRAFT || this == OPEN;
598	            case DRAFT -> false;
599	        };
600	    }
