643	/**
644	 * The sheet's figures as the screen shows them: each person's claimed and due-total, and the sheet's
645	 * claimed-total and due-total. A change takes a snapshot before it and, once its own audit lines are
646	 * written, records a ROLLUP line per person whose figures moved and a TOTALS line when the totals did.
647	 */
648	@Service
649	public class RollupService {
650	
651	    /** A person's figures, as text with two decimals; the due-total is "n/a" when they have none. */
652	    public record Figures(String name, String claimed, String dueTotal) {}
653	
654	    /** Each person's figures by id, in the order they were added, and the sheet's totals. */
655	    public record Rollup(Map<Long, Figures> people, String claimedTotal, String dueTotal) {}
656	
657	    private final PersonRepository people;
658	    private final ClaimRepository claims;
659	    private final RateRepository rates;
660	    private final SheetRepository sheets;
661	    private final Audit audit;
662	
663	    public RollupService(PersonRepository people, ClaimRepository claims, RateRepository rates,
664	            SheetRepository sheets, Audit audit) {
665	        this.people = people;
666	        this.claims = claims;
667	        this.rates = rates;
668	        this.sheets = sheets;
669	        this.audit = audit;
670	    }
671	
672	    /**
673	     * The sheet's figures now. Only open and settled claims count; a person's due-total is the sum of
674	     * their figures (those with one), n/a when their grade has no rate in force on the sheet's today
675	     * and no counting claim of theirs keeps a fixed (settled or stated) figure.
676	     */
677	    @Transactional(readOnly = true)
678	    public Rollup snapshot(String sheetId) {
679	        LocalDate today = sheets.findById(sheetId).map(Sheet::getToday).orElseGet(LocalDate::now);
680	        Map<Long, List<Claim>> byPerson = claims.findBySheetIdOrderByIdDesc(sheetId).stream()
681	                .filter(c -> c.getStatus().counts())
682	                .collect(Collectors.groupingBy(Claim::getPersonId));
683	        Map<Long, Figures> out = new LinkedHashMap<>();
684	        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
685	        BigDecimal dueTotal = BigDecimal.ZERO.setScale(2);
686	        for (Person p : people.findBySheetIdOrderByIdAsc(sheetId)) {
687	            List<Claim> counted = byPerson.getOrDefault(p.getId(), List.of());
688	            BigDecimal claimed = BigDecimal.ZERO.setScale(2);
689	            BigDecimal due = BigDecimal.ZERO.setScale(2);
690	            for (Claim c : counted) {
691	                claimed = claimed.add(c.getAmount());
692	                BigDecimal figure = figure(sheetId, p, c);
693	                if (figure != null) due = due.add(figure);
694	            }
695	            boolean rated = rates.findInForce(sheetId, p.getGrade(), today).isPresent();
696	            boolean anyFixed = counted.stream().anyMatch(c -> c.getDue() != null || c.isStated());
697	            claimedTotal = claimedTotal.add(claimed);
698	            if (rated || anyFixed) dueTotal = dueTotal.add(due);
699	            out.put(p.getId(), new Figures(p.getName(), text(claimed), rated || anyFixed ? text(due) : "n/a"));
700	        }
701	        return new Rollup(out, text(claimedTotal), text(dueTotal));
702	    }
703	
704	    /**
705	     * Record, once the change commits, a ROLLUP line for each person whose figures moved since
706	     * {@code before} (a person who did not exist then counts as moved), then a TOTALS line when the
707	     * sheet's totals moved.
708	     */
709	    @Transactional(readOnly = true)
710	    public void recordChanges(String sheetId, String user, Rollup before) {
711	        Rollup after = snapshot(sheetId);
712	        List<String> lines = new ArrayList<>();
713	        after.people().forEach((id, now) -> {
714	            Figures was = before.people().get(id);
715	            if (was == null || !was.claimed().equals(now.claimed()) || !was.dueTotal().equals(now.dueTotal())) {
716	                lines.add("ROLLUP sheet=" + sheetId + " by=" + user + " person=" + now.name()
717	                        + " claimed=" + now.claimed() + " due-total=" + now.dueTotal());
718	            }
719	        });
720	        if (!Objects.equals(before.claimedTotal(), after.claimedTotal())
721	                || !Objects.equals(before.dueTotal(), after.dueTotal())) {
722	            lines.add("TOTALS sheet=" + sheetId + " by=" + user + " claimed-total=" + after.claimedTotal()
723	                    + " due-total=" + after.dueTotal());
724	        }
725	        lines.forEach(audit::recordOnCommit);
726	    }
727	
728	    /**
729	     * The figure a claim shows: a settled claim's fixed due, else the figure its person's last
730	     * statement bound it to, else its amount times the rate in force on its date; null when none.
731	     */
732	    @Transactional(readOnly = true)
733	    public BigDecimal figure(String sheetId, Person person, Claim claim) {
734	        if (claim.getDue() != null) return claim.getDue();
735	        if (claim.isStated()) return claim.getStatedDue();
736	        return rates.findInForce(sheetId, person.getGrade(), claim.getDate())
737	                .map(rate -> due(claim.getAmount(), rate))
738	                .orElse(null);
739	    }
740	
741	    /** The amount times the rate's percent, rounded half to even to cents (as the screen works it out). */
742	    private static BigDecimal due(BigDecimal amount, Rate rate) {
743	        return amount.multiply(rate.getPct()).movePointLeft(2).setScale(2, RoundingMode.HALF_EVEN);
744	    }
745	
746	    private static String text(BigDecimal amount) {
747	        return amount.setScale(2).toPlainString();
748	    }
749	}
