);
CREATE INDEX statement_person ON statement (sheet_id, person_id, id);
-- A claim bound by its person's last statement shows and totals the figure it had then (stated_due,
-- null: n/a) until the next statement rebinds or unbinds it.
ALTER TABLE claim ADD COLUMN stated BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE claim ADD COLUMN stated_due DECIMAL(15, 2);
-- A sheet: everything else in the app is kept per sheet, keyed by its id.
CREATE TABLE sheet (
    id         VARCHAR(100) PRIMARY KEY,
    created_by VARCHAR(100) NOT NULL,
    created_at TIMESTAMP    NOT NULL
);
-- The sheet's "today": every date-dependent decision and default date in the sheet uses it, never
-- the real clock. A new sheet starts it at the real date.
ALTER TABLE sheet ADD COLUMN today DATE;
UPDATE sheet SET today = CAST(created_at AS DATE);
ALTER TABLE sheet ALTER COLUMN today SET NOT NULL;
-- A person on a sheet: a name and a grade (A, B or C). Listed in the order they were added (id).
CREATE TABLE person (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    name     VARCHAR(200) NOT NULL,
    grade    VARCHAR(1)   NOT NULL CHECK (grade IN ('A', 'B', 'C'))
);
CREATE INDEX person_sheet ON person (sheet_id, id);
-- A person's name is unique on the sheet, compared without regard to case. Names are stored with
-- surrounding spaces removed.
UPDATE person SET name = TRIM(name);
ALTER TABLE person ADD COLUMN name_key VARCHAR(200) GENERATED ALWAYS AS (LOWER(name));
CREATE UNIQUE INDEX person_sheet_name ON person (sheet_id, name_key);
-- A claim a person makes: an amount (0.00 or more, two decimals), a date and a note (may be
-- empty). Listed under its person newest first (id).
CREATE TABLE claim (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(100)   NOT NULL REFERENCES sheet (id),
    person_id  BIGINT         NOT NULL REFERENCES person (id),
    amount     DECIMAL(15, 2) NOT NULL CHECK (amount >= 0),
    claim_date DATE           NOT NULL,
    note       VARCHAR(1000)  NOT NULL
);
CREATE INDEX claim_sheet ON claim (sheet_id, id);
-- The sheet's rate for a grade: a percent with two decimals (0.00 or more). A grade has at most one
-- rate on a sheet; setting it again replaces it. A grade with no rate has none.
CREATE TABLE rate (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    grade    VARCHAR(1)   NOT NULL CHECK (grade IN ('A', 'B', 'C')),
    pct      DECIMAL(5, 2) NOT NULL CHECK (pct >= 0)
);
CREATE UNIQUE INDEX rate_sheet_grade ON rate (sheet_id, grade);
-- A claim's status: DRAFT when added; DRAFT -> OPEN -> SETTLED, and DRAFT or OPEN -> VOID. SETTLED
-- and VOID are final. Only OPEN and SETTLED claims count toward claimed and due.
ALTER TABLE claim ADD COLUMN status VARCHAR(10) DEFAULT 'DRAFT' NOT NULL
    CHECK (status IN ('DRAFT', 'OPEN', 'SETTLED', 'VOID'));
-- A claim's number: given when it is opened, the next on its sheet (1, 2, ...), never reused. A
-- draft has none, and voiding clears it. The sheet keeps the last number it gave out.
ALTER TABLE claim ADD COLUMN number INT;
ALTER TABLE sheet ADD COLUMN last_claim_number INT DEFAULT 0 NOT NULL;
UPDATE claim c SET number = (
    SELECT COUNT(*) FROM claim o
    WHERE o.sheet_id = c.sheet_id AND o.status IN ('OPEN', 'SETTLED') AND o.id <= c.id)
WHERE c.status IN ('OPEN', 'SETTLED');
UPDATE sheet s SET last_claim_number = COALESCE((SELECT MAX(number) FROM claim c WHERE c.sheet_id = s.id), 0);
CREATE UNIQUE INDEX claim_sheet_number ON claim (sheet_id, number);
-- A settled claim's due, fixed when it is settled: its amount times its person's grade's rate then,
-- rounded half up to cents. Later changes to rates (or grades) do not alter it. Open and other
-- claims have none (their due stays live), as does one settled while its grade had no rate.
ALTER TABLE claim ADD COLUMN due DECIMAL(15, 2);
UPDATE claim c SET due = (
    SELECT ROUND(c.amount * r.pct / 100, 2) FROM person p JOIN rate r
        ON r.sheet_id = p.sheet_id AND r.grade = p.grade
    WHERE p.id = c.person_id)
WHERE c.status = 'SETTLED';

